function buildAwardBrand(name) {
    const meta = AWARD_LOGOS[name];
    if (!meta) {
        // No logo on file — show the award body's name as a styled text badge
        return `<div class="award-brand-row"><span class="award-brand-text">${name}</span></div>`;
    }
    if (meta.type === "svg") {
        return `<div class="award-brand-row">${oscarBrandSVG}</div>`;
    }
    const cls = meta.recolor ? "award-brand-logo recolor" : "award-brand-logo";
    return `<div class="award-brand-row"><img class="${cls}" src="${meta.src}" alt="${name} logo"></div>`;
}

function renderAwardsSection(movie) {
    const section = document.getElementById('awardsSection');
    section.innerHTML = '';

    let awardMap = MOVIE_AWARDS[movie.Title];

    if (!awardMap) {
        // Detect the actual ceremony(ies) mentioned in OMDb's Awards text instead of
        // always assuming the Oscars — OMDb typically only calls out wins from
        // Academy Awards, Emmys, Golden Globes, and BAFTA in this "Won N X" phrasing.
        const AWARD_MATCHERS = [
            { name: "Academy Awards", re: /Won (\d+) Oscars?/i },
            { name: "Emmy Awards", re: /Won (\d+) (?:Primetime )?Emmys?/i },
            { name: "Golden Globes", re: /Won (\d+) Golden Globes?/i },
            { name: "BAFTA", re: /Won (\d+) BAFTA(?: Film)? Awards?/i }
        ];
        const CATEGORY_TEMPLATES = {
            "Academy Awards": ["Best Picture", "Best Director", "Best Actor", "Best Screenplay"],
            "Emmy Awards": ["Outstanding Series", "Outstanding Directing", "Outstanding Lead Actor", "Outstanding Writing"],
            "Golden Globes": ["Best Motion Picture", "Best Director", "Best Actor", "Best Screenplay"],
            "BAFTA": ["Best Film", "Best Director", "Best Actor", "Best Screenplay"]
        };
        const actorLead = movie.Actors.split(',')[0]?.trim() || "Lead Performance";
        const writerLead = movie.Writer.split(',')[0]?.trim() || "Original Screenplay";
        const RECIPIENTS = {
            "Best Picture": "Award Winner", "Best Motion Picture": "Award Winner", "Best Film": "Award Winner", "Outstanding Series": "Award Winner",
            "Best Director": movie.Director, "Outstanding Directing": movie.Director,
            "Best Actor": actorLead, "Outstanding Lead Actor": actorLead,
            "Best Screenplay": writerLead, "Outstanding Writing": writerLead
        };

        const detected = AWARD_MATCHERS
            .map(m => ({ name: m.name, count: (movie.Awards.match(m.re) || [])[1] }))
            .filter(m => m.count);

        if (detected.length) {
            awardMap = {};
            detected.forEach(({ name, count }) => {
                const templates = CATEGORY_TEMPLATES[name] || ["Award Won"];
                awardMap[name] = templates.slice(0, Math.max(parseInt(count, 10), 1)).map(category => ({
                    category,
                    recipient: RECIPIENTS[category] || null
                }));
            });
        } else {
            // No recognized top-tier ceremony in the text (e.g. only festival/critics
            // wins, or just an aggregate "N wins & N nominations") — show the raw
            // OMDb line instead of fabricating a specific ceremony/logo.
            awardMap = {
                "Award Recognition": [
                    { category: "Recognized For", recipient: movie.Awards }
                ]
            };
        }
    }

    Object.keys(awardMap).forEach(awardName => {
        const wins = awardMap[awardName];
        if (!wins || wins.length === 0) return;

        const body = document.createElement('div');
        body.className = 'award-body';

        const wreaths = wins.map(item => `
            <div class="wreath-card">
                ${laurelWreathSVG}
                <div class="wreath-content">
                    <div class="award-category">${item.category}</div>
                    ${item.recipient ? `<div class="award-recipient">${item.recipient}</div>` : ''}
                </div>
            </div>
        `).join('');

        body.innerHTML = `
            ${buildAwardBrand(awardName)}
            <div class="section-subtitle">${awardName} Wins</div>
            <div class="wreath-grid">${wreaths}</div>
        `;

        section.appendChild(body);
    });
}

window.openAwardsModal=async function(){const e=document.getElementById("awards-modal");if(!e)return;const t=document.getElementById("am-loading"),n=document.getElementById("am-empty"),r=document.getElementById("awardsSection"),o=document.getElementById("omdbSummary");e.classList.remove("hidden"),document.body.style.overflow="hidden",window.toggleMobileNav&&window.toggleMobileNav(!0),t.classList.remove("hidden"),n.classList.add("hidden"),o.classList.add("hidden"),o.textContent="",r.innerHTML="";try{const e=IMDB_ID?await fetchOMDBRatings(IMDB_ID):null;if(t.classList.add("hidden"),!e||!e.awards)return void n.classList.remove("hidden");o.textContent=e.awards,o.classList.remove("hidden"),renderAwardsSection({Title:currentTitle||"",Awards:e.awards,Director:e.director||"",Actors:e.actors||"",Writer:e.writer||""})}catch(e){console.warn("[Awards] fetch failed:",e),t.classList.add("hidden"),n.classList.remove("hidden")}};
window.closeAwardsModal=function(){const e=document.getElementById("awards-modal");e&&(e.classList.add("hidden"),document.body.style.overflow="",window.toggleMobileNav&&window.toggleMobileNav(!1))};
